```java
import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

public class SecureServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("userInput");
        // Safe: Validating and sanitizing user input before executing any command.
        if (isValidCommand(userInput)) {
            executeCommand(userInput);
        } else {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid command");
        }
    }

    private boolean isValidCommand(String command) {
        // Implement a whitelist of allowed commands.
        return command.matches("^[a-zA-Z0-9\\s\\-\\_\\+\\.]+");
    }

    private void executeCommand(String command) {
        try {
            Process process = Runtime.getRuntime().exec(command);
            process.waitFor();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

